mapper.select:
with recursive visible as ( select f.* from ai_knowledge_folder f where f.knowledge_base_id = #{baseId}
and f.data_status = #{dataStatus}
union select entry.* from ai_knowledge_folder entry join ai_knowledge_document d on d.folder_id = entry.id and d.knowledge_base_id = entry.knowledge_base_id where entry.knowledge_base_id = #{baseId}
and entry.data_status = #{dataStatus}
), paths as ( select * from visible union select p.* from ai_knowledge_folder p join paths child on p.id = child.parent_id and p.knowledge_base_id = child.knowledge_base_id where p.knowledge_base_id = #{baseId} ) select * from paths order by sort_order, id

with recursive ancestors as (
    select id, parent_id, tenant_id, knowledge_base_id
    from ai_knowledge_folder
    where id = #{targetId}
      and knowledge_base_id = #{baseId}
    union
    select p.id, p.parent_id, p.tenant_id, p.knowledge_base_id
    from ai_knowledge_folder p
    join ancestors a on p.id = a.parent_id
    where p.knowledge_base_id = #{baseId}
)
select count(*)
from ancestors
where id = #{folderId}

with occupied as (
    select id, tenant_id
    from ai_knowledge_folder
    where knowledge_base_id = #{baseId}

        and parent_id = #{folderId}

    union all
    select id, tenant_id
    from ai_knowledge_document
    where knowledge_base_id = #{baseId}

        and folder_id = #{folderId}

)
select count(*)
from occupied
